// Medidor de corriente con el sensor ACS712 (modelo de 5 A)
const int SENSOR = A0;        // OUT del sensor
const int ZUMBADOR = 8;
const int LED_ALERTA = 9;
const float SENSIBILIDAD = 0.185;   // voltios por cada amperio
const float LIMITE = 2.0;           // amperios para dar la alarma

void setup() {
  Serial.begin(9600);
  pinMode(ZUMBADOR, OUTPUT);
  pinMode(LED_ALERTA, OUTPUT);
}

void loop() {
  int lectura = analogRead(SENSOR);          // 0 a 1023 (512 = sin corriente)
  float voltaje = lectura * 5.0 / 1023.0;
  float corriente = (voltaje - 2.5) / SENSIBILIDAD;

  Serial.print("Corriente: ");
  Serial.print(corriente, 2);
  Serial.println(" A");

  if (abs(corriente) > LIMITE) {
    digitalWrite(LED_ALERTA, HIGH);
    tone(ZUMBADOR, 1500, 150);
  } else {
    digitalWrite(LED_ALERTA, LOW);
  }
  delay(500);
}
